def solve_game(N):
    # P[n] = True if n is a P-position (losing for current player)
    # P[n] = False if n is an N-position (winning for current player)
    # We analyze states from N down to 1.

    P = [False] * (N + 1)

    # The terminal state N means the previous player won, so we analyze moves leading to N.

    # Base cases for N:
    # If n=N-1, a move to N wins. So N-1 is N-position (P[N-1] = False).
    if N > 0:
        if N - 1 >= 1:
            P[N-1] = False

        # If N is even, N/2 can move to N. So N/2 is N-position (P[N/2] = False).
        if N % 2 == 0 and N//2 >= 1:
             P[N//2] = False

    # Iterate backwards from N-2 down to 1
    for n in range(N - 2, 0, -1):
        moves = []
        if n + 1 <= N:
            moves.append(n + 1)
        if 2 * n <= N:
            moves.append(2 * n)

        # n is P if ALL possible moves lead to N-positions (not P-positions)
        # n is N if ANY possible move leads to a P-position

        is_p_position = True

        # Check all successor positions m
        for m in moves:
            # If m is a P-position (P[m] is True), then moving to m is a winning strategy.
            if P[m] == True:
                is_p_position = False # Found a winning move, so n is N-position
                break

        P[n] = is_p_position

    # P[1] == True means 1 is a P-position, thus N is Type B.
    return P[1]

