def solve_game(N):
    # dp[n] will store True if position n is a Winning position (N-position) for the current player, 
    # and False if it is a Losing position (P-position).
    # We only need to store up to N-1.
    dp = {}

    # Base case is N. The player reaching N wins.
    # We iterate backwards from N-1 down to 1.
    for n in range(N - 1, 0, -1):

        can_win = False

        # Check move n+1
        m1 = n + 1
        if m1 == N:
            can_win = True
        elif m1 < N:
            # If the opponent loses from m1 (i.e., dp[m1] is False), then we win by moving there.
            if not dp.get(m1, False): # Should always be defined if we iterate correctly
                can_win = True

        if can_win:
            dp[n] = True
            continue

        # Check move 2*n
        m2 = 2 * n
        if m2 == N:
            can_win = True
        elif m2 < N:
            # If the opponent loses from m2, we win by moving there.
            if not dp.get(m2, False):
                can_win = True

        dp[n] = can_win

    return dp.get(1, False) # Returns True if N is Type A, False if N is Type B

